		/** 
		 * Tests creating a new Subscription.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Subscription");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Subscription" );

			try {            
				Subscription entity = SubscriptionService.getSubscriptionInstance().createSubscription( generateNewEntity() );
				thePrimaryKey = entity.getSubscriptionId();
				LOGGER.info( "-- Successfully created a Subscription with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Subscription. 
		 */
		public Subscription testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Subscription" );

			Subscription entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Subscription with primary key" );
			msg.append( thePrimaryKey );
			
			SubscriptionFetchOneSummary fetchOneSummary = new SubscriptionFetchOneSummary( thePrimaryKey );

			try {
				entity = SubscriptionService.getSubscriptionInstance().getSubscription( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Subscription " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Subscription.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Subscription." );

			StringBuilder msg = new StringBuilder( "Failed to update a Subscription : " );        
			Subscription entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Subscription." );

				// for use later on...
				thePrimaryKey = entity.getSubscriptionId();

				SubscriptionService proxy = SubscriptionService.getSubscriptionInstance();            
				proxy.updateSubscription( entity );   

				LOGGER.info( "-- Successfully saved Subscription - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Subscription.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Subscription." );

			try{
			    Subscription entity = testRead(); 
				SubscriptionService.getSubscriptionInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Subscription with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Subscription with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Subscriptions.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Subscriptions:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Subscription : " );        
			List<Subscription> collection  = null;

			try {
				// call the static get method on the SubscriptionService
				collection = SubscriptionService.getSubscriptionInstance().getAllSubscription();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Subscription entity = null;            
					Iterator<Subscription> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getSubscriptionId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

